"""hexcap_exact: parametric CadQuery model generated by stl2cad (exact mode, 2.5D).

The part is built along +z from 2 extrusion(s) and 3 cut(s), applied in order;
each is an outline in the xy plane between two levels. Units: mm.
Run:  python hexcap_exact.py [out.step]
"""

import math
import sys

from cadquery import Edge, Vector
from cadquery import func as cf

# ---- parameters ----------------------------------------------------------
z0 = -15.24    # level along z
z1 = -11.43    # level along z
z2 = -7.62    # level along z
z3 = 0.0    # level along z
hole_d = 3.175

DIR = (0, 0, 1)


def P(a, b):
    """Point (x, y) in the sketch plane (z = 0)."""
    return (a, b, 0)


def prism(outline, lo, hi):
    """Outline extruded from level lo to level hi."""
    body = cf.extrude(cf.face(outline), [(hi - lo) * c for c in DIR])
    return body.translate(Vector(*[lo * c for c in DIR]))


def hole(a, b, d, lo, hi):
    return prism(Edge.makeCircle(d / 2, P(a, b), DIR), lo, hi)


# ---- 1. extrusion: z -15.24 to -11.43 ------------------------------
outline_1 = cf.wire(
    Edge.makeEllipse(20.32, 6.35, P(0.0, 0.0), DIR, P(1, 0)),
)
part = prism(outline_1, z0, z1)

# ---- 2. extrusion: z -11.43 to 0.0 ------------------------------
outline_2 = cf.wire(
    Edge.makeCircle(5.715, P(0.0, 0.0), DIR),
)
part = part + prism(outline_2, z1, z3)

# ---- round holes: (x, y, diameter, from, to) ------------------------
for a, b, d, lo, hi in [
    (15.875, 0.0, hole_d, z0, z1),
    (-15.875, 0.0, hole_d, z0, z1),
]:
    part = part - hole(a, b, d, lo, hi)

# ---- 3. cut: z -7.62 to 0.0 ------------------------------
outline_3 = cf.wire(
    cf.segment(P(-1.8331, 3.175), P(1.8331, 3.175)),
    cf.segment(P(1.8331, 3.175), P(3.6662, 0.0)),
    cf.segment(P(3.6662, 0.0), P(1.8331, -3.175)),
    cf.segment(P(1.8331, -3.175), P(-1.8331, -3.175)),
    cf.segment(P(-1.8331, -3.175), P(-3.6662, 0.0)),
    cf.segment(P(-3.6662, 0.0), P(-1.8331, 3.175)),
)
part = part - prism(outline_3, z2, z3)

part = part.clean()

if __name__ == "__main__":
    part.exportStep(sys.argv[1] if len(sys.argv) > 1 else "hexcap_exact.step")
